import type { createAdminClient } from "@/lib/supabase/admin"

type Admin = ReturnType<typeof createAdminClient>

function utcDayStart(): string {
  const d = new Date()
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate())).toISOString()
}

/**
 * Recommendations the user generated by hand today (UTC), across all sites.
 * Counted from the generation log (migration 018), because each regeneration
 * deletes the previous batch: counting surviving rows let the limit reset after
 * every run. Falls back to counting today's rows if the log isn't there yet.
 */
export async function manualRecsUsedToday(admin: Admin, userId: string, siteIds: string[]): Promise<number> {
  const since = utcDayStart()
  const { data, error } = await admin
    .from("recommendation_generations")
    .select("rec_count")
    .eq("user_id", userId)
    .eq("source", "manual")
    .gte("created_at", since)
  if (!error) return (data ?? []).reduce((sum, r) => sum + (r.rec_count || 0), 0)

  if (siteIds.length === 0) return 0
  const { count } = await admin
    .from("recommendations")
    .select("id", { count: "exact", head: true })
    .in("site_id", siteIds)
    .gte("created_at", since)
  return count ?? 0
}

/** Whether recommendations were auto-generated for this site recently (sync/cron), to stop "delete recs, re-sync" loops. */
export async function autoGeneratedRecently(admin: Admin, siteId: string, hours = 24): Promise<boolean> {
  const { data, error } = await admin
    .from("recommendation_generations")
    .select("id")
    .eq("site_id", siteId)
    .eq("source", "auto")
    .gte("created_at", new Date(Date.now() - hours * 3600_000).toISOString())
    .limit(1)
  if (error) return false // log not there yet: keep the old behaviour
  return (data ?? []).length > 0
}

export async function logGeneration(
  admin: Admin,
  entry: { userId: string; siteId: string; source: "manual" | "auto"; recCount: number }
): Promise<void> {
  const { error } = await admin.from("recommendation_generations").insert({
    user_id: entry.userId,
    site_id: entry.siteId,
    source: entry.source,
    rec_count: entry.recCount,
  })
  if (error && !/recommendation_generations/.test(error.message)) {
    console.error("Failed to log recommendation generation:", error.message)
  }
}
